using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using Godot;
using OpenAntares.Game.Presentation;
using OpenAntares.Simulation;
using OpenAntares.Simulation.Commands;
using OpenAntares.Simulation.Content;
using OpenAntares.Simulation.Development;
using OpenAntares.Simulation.Knowledge;
namespace OpenAntares.Game.Components;
public partial class EmpireManagementDialog:AcceptDialog
{
    private OpenAntares.Game.Presentation.PlanetStyleCatalog? _styles;private OpenAntares.Game.Presentation.PlanetPortraitCache? _cache;private readonly PlanetPortrait _portrait=new(){Name="ManagementPortraitSlot"};
    public void ConfigurePortraits(OpenAntares.Game.Presentation.PlanetStyleCatalog styles,OpenAntares.Game.Presentation.PlanetPortraitCache cache){_styles=styles;_cache=cache;_portrait.Configure(styles,cache);}
    public event Action<Command>? CommandIssued;public event Action<ColonyId>? ColonyRequested;
    public ColonyNotificationPreferences Preferences{get;set;}=ColonyNotificationPreferences.Defaults;
    private readonly OptionButton _filter=new(){Name="ManagementFilter"},_template=new(){Name="BulkTemplatePicker"},_inherit=new(){Name="NewColonyTemplatePicker"};
    private readonly ItemList _list=new(){Name="ManagementColonyList",SelectMode=ItemList.SelectModeEnum.Multi,CustomMinimumSize=new(0,160),FixedIconSize=new(48,48)};
    private readonly CheckBox _workforce=new(){Name="BulkWorkforce",Text="Manage workforce",ButtonPressed=true},_construction=new(){Name="BulkConstruction",Text="Manage construction",ButtonPressed=true},_replace=new(){Name="BulkReplaceActive",Text="Confirm replacing active projects; retain reserves"};
    private readonly CheckBox _inheritWorkforce=new(){Text="New colonies: workforce automation"},_inheritConstruction=new(){Text="New colonies: construction automation"};
    private readonly Label _preview=DevelopmentUi.Text(""),_detail=DevelopmentUi.Text(""),_inheritStatus=DevelopmentUi.Text("");private readonly GovernorReportPanel _reports=new();private readonly List<OwnedColonyView> _rows=new();private readonly Dictionary<ColonyId,ImmutableArray<GovernorIssue>> _issues=new();private readonly Dictionary<ColonyId,GovernorColonyOrder> _plans=new();private ContentSet? _content;private EmpireView? _view;
    public override void _Ready(){Title="Manage colonies";OkButtonText="Close";Name="EmpireManagementDialog";var body=DevelopmentUi.DialogBody(this);body.AddChild(_filter);body.AddChild(_list);var selection=new HBoxContainer();body.AddChild(selection);DevelopmentUi.Button(selection,"Select all",()=>{for(int i=0;i<_list.ItemCount;i++)_list.Select(i,false);Preview();});DevelopmentUi.Button(selection,"Clear selection",()=>{_list.DeselectAll();Preview();});DevelopmentUi.Button(selection,"Inspect colony",()=>{int i=_list.GetSelectedItems().FirstOrDefault(-1);if(i>=0){Hide();ColonyRequested?.Invoke(_rows[i].Id);}});body.AddChild(_portrait);body.AddChild(_detail);body.AddChild(_template);body.AddChild(_workforce);body.AddChild(_construction);body.AddChild(_replace);body.AddChild(_preview);DevelopmentUi.Button(body,"Apply to selected colonies",Apply,"BulkApplyTemplate");body.AddChild(new HSeparator());body.AddChild(DevelopmentUi.Text("Optional new-colony inheritance. Defaults to off and starts after founding."));body.AddChild(_inherit);body.AddChild(_inheritWorkforce);body.AddChild(_inheritConstruction);DevelopmentUi.Button(body,"Apply new-colony plan",()=>{string id=_inherit.GetSelectedMetadata().AsString();CommandIssued?.Invoke(new SetNewColonyPlanCommand(_view!.Viewer,_view.Turn,id.Length==0?null:id,_inheritWorkforce.ButtonPressed,_inheritConstruction.ButtonPressed));});body.AddChild(_inheritStatus);body.AddChild(_reports);_filter.ItemSelected+=_=>Rows();_template.ItemSelected+=_=>Preview();_workforce.Toggled+=_=>Preview();_construction.Toggled+=_=>Preview();_replace.Toggled+=_=>Preview();_list.MultiSelected+=(_,_)=>Preview();}
    public void ShowEmpire(ContentSet content,EmpireView view){_content=content;_view=view;if(view.Development is null)return;string filter=_filter.ItemCount>0?_filter.GetSelectedMetadata().AsString():"all";_filter.Clear();foreach(string id in new[]{"all","exceptions","healthy","manual"}){_filter.AddItem(id);_filter.SetItemMetadata(_filter.ItemCount-1,id);}foreach(var t in content.GovernorTemplates.Values){_filter.AddItem(t.Name);_filter.SetItemMetadata(_filter.ItemCount-1,"template:"+t.Id);}foreach(var t in view.Development.CustomTemplates){_filter.AddItem(t.Definition.Name);_filter.SetItemMetadata(_filter.ItemCount-1,"template:"+t.Id);}for(int i=0;i<_filter.ItemCount;i++)if(_filter.GetItemMetadata(i).AsString()==filter)_filter.Select(i);FillTemplates(_template,"Manual / no template");FillTemplates(_inherit,"No inheritance");var inherited=view.Development.NewColonyPlan;for(int i=0;i<_inherit.ItemCount;i++)if(_inherit.GetItemMetadata(i).AsString()==inherited?.Template.Id)_inherit.Select(i);_inheritWorkforce.SetPressedNoSignal(inherited?.WorkforceEnabled??false);_inheritConstruction.SetPressedNoSignal(inherited?.ConstructionEnabled??false);_inheritStatus.Text=inherited is null?"New-colony inheritance is off.":$"Assigned {inherited.Template.Definition.Name}, revision {inherited.Template.Revision}; later library edits do not propagate.";var plan=GovernorPlanner.Plan(GovernorPlanningQueries.Create(content,view));_plans.Clear();if(plan.Succeeded)foreach(var order in plan.Orders)_plans[order.Colony]=order;_issues.Clear();foreach(var c in view.Colonies)_issues[c.Id]=GovernorReportPanel.CurrentIssues(content,view,c,plan);Rows();_reports.Preferences=Preferences;_reports.ShowReports(content,view);PopupCenteredClamped(new(880,650));}
    private void FillTemplates(OptionButton picker,string manual){string old=picker.ItemCount>0?picker.GetSelectedMetadata().AsString():"";picker.Clear();picker.AddItem(manual);picker.SetItemMetadata(0,"");foreach(var t in _content!.GovernorTemplates.Values){picker.AddItem(t.Name);picker.SetItemMetadata(picker.ItemCount-1,t.Id);}foreach(var t in _view!.Development!.CustomTemplates){picker.AddItem(t.Definition.Name);picker.SetItemMetadata(picker.ItemCount-1,t.Id);}for(int i=0;i<picker.ItemCount;i++)if(picker.GetItemMetadata(i).AsString()==old)picker.Select(i);}
    private void Rows(){_list.Clear();_rows.Clear();string filter=_filter.GetSelectedMetadata().AsString();foreach(var c in _view!.Colonies.OrderBy(c=>c.Id)){bool issues=_issues[c.Id].Length>0;var d=c.Development!;if(filter=="exceptions"&&!issues||filter=="healthy"&&issues||filter=="manual"&&(d.WorkforceEnabled||d.ConstructionEnabled)||filter.StartsWith("template:",StringComparison.Ordinal)&&d.Template?.Id!=filter[9..])continue;_rows.Add(c);string row=$"{_view.Research.ColonyNames[c.Id.ToString()]} | {d.Template?.Definition.Name??"Manual"} | workforce {(d.WorkforceEnabled?"auto":"manual")} / build {(d.ConstructionEnabled?"auto":"manual")} | current {ProjectName(c)}, next {NextName(c)} | P {Format.Points(c.Economy.NetProduction.Total)} R {Format.Points(c.Economy.NetResearch.Total)} | {(_issues[c.Id].Length==0?"healthy":string.Join("; ",_issues[c.Id].Select(i=>GovernorReportPanel.IssueText(_content!,i))))}";_list.AddItem(row);_list.SetItemTooltip(_list.ItemCount-1,row);var known=Known(c);if(known?.Appearance is {} appearance&&_styles is not null&&_cache is not null)_list.SetItemIcon(_list.ItemCount-1,_cache.Get(appearance,_styles.Resolve(known.PlanetTypeId,known.EnvironmentId,appearance.Variant),new(64,64)));}Preview();}
    private GovernorTemplateSnapshot? Selected(){string id=_template.GetSelectedMetadata().AsString();if(id.Length==0)return null;if(_content!.GovernorTemplates.TryGetValue(id,out var t))return new(id,1,new(t.Name,t.FoundationIds,t.DevelopmentIds,t.SupportTarget,t.ProductionWeight,t.ResearchWeight));return _view!.Development!.CustomTemplates.Single(t=>t.Id==id);}
    private void Preview(){if(_view is null||_content is null)return;var selected=_list.GetSelectedItems().Select(i=>_rows[i]).ToArray();_portrait.ShowPlanet(selected.Length==1?Known(selected[0]):null);_preview.Text=selected.Length==0?"Select colonies for an atomic before/after preview.":string.Join("\n",selected.Select(c=>{var preview=GovernorPlanningQueries.Preview(_content,_view,c.Id,Selected(),_workforce.ButtonPressed&&Selected() is not null,_construction.ButtonPressed);return $"{_view.Research.ColonyNames[c.Id.ToString()]}: S/P/R {c.Workforce.Support}/{c.Workforce.Production}/{c.Workforce.Research} to {preview?.Workforce.Support??c.Workforce.Support}/{preview?.Workforce.Production??c.Workforce.Production}/{preview?.Workforce.Research??c.Workforce.Research}; active work {(_replace.ButtonPressed?"replaced":"retained")}, reserve {Format.Points(c.ProductionReserve)} retained.";}));_detail.Text=selected.Length==1?$"Current project: {ProjectName(selected[0])}; next planned project: {NextName(selected[0])}. "+string.Join(" ",_issues[selected[0].Id].Select(i=>GovernorReportPanel.IssueText(_content,i))):$"{selected.Length} selected; {_rows.Count} shown / {_view.Colonies.Length} owned.";}
    private string ProjectName(OwnedColonyView c)=>c.ProjectId is null?"bank production":c.ProjectKind=="building"?_content!.Buildings[c.ProjectId].Name:_content!.Vessels[c.ProjectId].Name;
    private KnownPlanetView? Known(OwnedColonyView c)=>_view!.Stars.FirstOrDefault(s=>s.Chart.Id==c.StarId)?.Planets?.FirstOrDefault(p=>p.Id==c.PlanetId);
    private string NextName(OwnedColonyView c){var target=_plans.TryGetValue(c.Id,out var order)?order.Target:null;return target is null?"bank production":target.Kind=="building"?_content!.Buildings[target.ContentId].Name:_content!.Vessels[target.ContentId].Name;}
    private void Apply(){var ids=_list.GetSelectedItems().Select(i=>_rows[i].Id).ToImmutableArray();if(ids.IsEmpty){_preview.Text="Select at least one colony.";return;}CommandIssued?.Invoke(new AssignGovernorTemplateCommand(_view!.Viewer,_view.Turn,ids,Selected()?.Id,Selected() is not null&&_workforce.ButtonPressed,_construction.ButtonPressed,_replace.ButtonPressed));}
}
